import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"大過","description":"周易正义 - 大過","frontmatter":{"title":"大過","description":"周易正义 - 大過"},"headers":[],"relativePath":"zh/classics/zhengyi/028.md","filePath":"zh/classics/zhengyi/028.md"}'),l={name:"zh/classics/zhengyi/028.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>泽风大过</p></blockquote><blockquote><p>卦辞：栋桡，利有攸往，亨。</p></blockquote><blockquote><p>彖曰：大过，大者过也。栋挠，本末弱也。刚过而中，巽而说，行。利有攸往，乃亨。大过之时大矣哉！</p></blockquote><h1 id="大過" tabindex="-1">大過 <a class="header-anchor" href="#大過" aria-label="Permalink to “大過”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“大过”。○正义曰：“过”谓过越之“过”，非经过之“过”。此衰难之世，唯阳爻，乃大能过越常理以拯患难也。故曰“大过”。以人事言之，犹若圣人过越常理以拯患难也。○注“音相过之过”。○正义曰：“相过”者，谓相过越之甚也，非谓相过从之“过”，故《象》云“泽灭木”。是过越之甚也。四阳在中，二阴在外，以阳之过越之甚也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“栋挠”者，谓屋栋也。本之与末俱挠弱，以言衰乱之世，始终皆弱也。“利有攸往亨”者，既遭衰难，圣人“利有攸往”，以拯患难，乃得亨通，故云“利有攸往亨”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="大过-大者过也。-​" tabindex="-1">大过，大者过也。 ​ <a class="header-anchor" href="#大过-大者过也。-​" aria-label="Permalink to “大过，大者过也。 ​”">​</a></h3><p>王弼：大者乃能过也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释大过之义也。“大者过”，谓盛大者乃能过其分理以拯难也。故於二爻阳处阴位，乃能拯难也，亦是过甚之义。</p><h3 id="栋挠-本末弱也。-​" tabindex="-1">“栋挠”，本末弱也。 ​ <a class="header-anchor" href="#栋挠-本末弱也。-​" aria-label="Permalink to ““栋挠”，本末弱也。 ​”">​</a></h3><p>王弼：初为本，而上为末也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“栋挠”义。以大过本末俱弱，故屋栋挠弱也，似若衰难之时始终弱。</p><h3 id="刚过而中-​" tabindex="-1">刚过而中， ​ <a class="header-anchor" href="#刚过而中-​" aria-label="Permalink to “刚过而中， ​”">​</a></h3><p>王弼：谓二也。居阴，“过”也；处二，“中”也。拯弱兴衰，不失其中也。</p><h3 id="巽而说行-​" tabindex="-1">巽而说行， ​ <a class="header-anchor" href="#巽而说行-​" aria-label="Permalink to “巽而说行， ​”">​</a></h3><p>王弼：“巽而说行”，以此救难，难乃济也。</p><h3 id="利有攸往-乃亨。-​" tabindex="-1">“利有攸往”，乃亨。 ​ <a class="header-anchor" href="#利有攸往-乃亨。-​" aria-label="Permalink to ““利有攸往”，乃亨。 ​”">​</a></h3><p>王弼：危而弗持，则将安用？故往乃亨。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“刚过而中巽而说行利有攸往乃亨”者，此释“利有攸往乃亨”义。“刚过而中”谓二也。以阳处阴，是刚之过极之甚，则阳来拯此阴难，是过极之甚也。“巽而说行”者，既以巽顺和说而行，难乃得济，故“利有攸往得亨”也。故云“乃亨”。</p><h3 id="大过之时大矣哉-​" tabindex="-1">大过之时大矣哉！ ​ <a class="header-anchor" href="#大过之时大矣哉-​" aria-label="Permalink to “大过之时大矣哉！ ​”">​</a></h3><p>王弼：是君子有为之时也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此广说大过之美。言当此大过之时，唯君子有为拯难，其功甚大，故曰“大矣哉”也。</p><h2 id="象曰-泽灭木-大过。君子以独立不惧-遁世无闷。-​" tabindex="-1">象曰：泽灭木，大过。君子以独立不惧，遁世无闷。 ​ <a class="header-anchor" href="#象曰-泽灭木-大过。君子以独立不惧-遁世无闷。-​" aria-label="Permalink to “象曰：泽灭木，大过。君子以独立不惧，遁世无闷。 ​”">​</a></h2><p>王弼：此所以为“大过”，非凡所及也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“泽灭木”者，泽体处下，木体处上，泽无灭木之理。今云“泽灭木”者，乃是泽之甚极而至灭木，是极大过越之义。其大过之卦有二义也：一者物之自然大相过越常分，即此“泽灭木”是也。二者大人大过越常分以拯患难，则九二“枯杨生稊，老夫得其女妻”是也。“君子以独立不惧，遁世无闷”者，明君子於衰难之时，卓尔独立，不有畏惧，隐遁於世而无忧闷，欲有遁难之心，其操不改。凡人遇此则不能，然唯君子独能如此，是其过越之义。</p><h2 id="初六-藉用白茅-无咎。-​" tabindex="-1">初六：藉用白茅，无咎。 ​ <a class="header-anchor" href="#初六-藉用白茅-无咎。-​" aria-label="Permalink to “初六：藉用白茅，无咎。 ​”">​</a></h2><p>王弼：以柔处下，过而可以“无咎”，其唯慎乎！</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以柔处下，心能谨慎，荐藉於物，用絜白之茅，言以絜素之道奉事於上也。“无咎”者，既能谨慎如此，虽遇大过之难，而“无咎”也。以柔道在下，所以免害。故《象》云“柔在下也”。</p><h3 id="《象》曰-藉用白茅-柔在下也。-​" tabindex="-1">《象》曰：“藉用白茅”，柔在下也。 ​ <a class="header-anchor" href="#《象》曰-藉用白茅-柔在下也。-​" aria-label="Permalink to “《象》曰：“藉用白茅”，柔在下也。 ​”">​</a></h3><h2 id="九二-枯杨生稊-老夫得其女妻-无不利。-​" tabindex="-1">九二：枯杨生稊，老夫得其女妻，无不利。 ​ <a class="header-anchor" href="#九二-枯杨生稊-老夫得其女妻-无不利。-​" aria-label="Permalink to “九二：枯杨生稊，老夫得其女妻，无不利。 ​”">​</a></h2><p>王弼：“稊”者，杨之秀也。以阳处阴，能过其本而救其弱者也。上无其应，心无持吝处过以此，无衰不济也。故能令枯杨更生稊，老夫更得少妻，拯弱兴衰，莫盛斯爻，故“无不利”也。老过则枯，少过则稚。以老分少，则稚者长；以稚分老，则枯者荣，过以相与之谓也。大过至衰而已至壮，以至壮辅至衰，应斯义也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰藉用白茅”至“无不利”。○正义曰：“枯杨生稊”者，“枯”谓枯稿，“稊”谓“杨之秀”者。九二以阳处阴，能过其本分，而救其衰弱。上无其应，心无特吝，处大过之时，能行此道，无有衰者不被拯济。故衰者更盛，犹若枯槁之杨，更生少壮之稊；枯老之夫，得其少女为妻也。“无不利”者，谓拯弱兴衰，莫盛於此。以斯而行，无有不利也。○注“稊者杨之秀也”至“应斯义也”。○正义曰：“稊”者杨柳之穗，故云“杨之秀也”。“以阳处阴，能过其本而救其弱”者，若以阳处阳，是依其本分。今以阳处阴，是过越本分，拯救阴弱也。“老过则枯，少过则稚”者，老之太过则枯槁，少之太过则幼稚也。“以老分少则稚者长也”，谓老夫减老而与女妻，女妻得之而更益长，故云“以老分少则稚者长也”。“以稚分老则枯者荣”者，谓女妻减少而与老夫，老夫得之，似若槁者而更得生稊，故云“则枯者荣也。”云“大过至衰而已至壮，以至壮辅至衰，应斯义”者，此大过之卦，本明至壮辅至衰，不论至衰减至壮。故辅嗣此《注》特云“以至壮辅至衰也”。“《象》曰过以相与”者，因至壮而辅至衰，似女妻而助老夫，遂因云老夫减老而与少，犹若至衰减衰而与壮也。其实不然也。</p><h3 id="《象》曰-老夫女妻-过以相与也。-​" tabindex="-1">《象》曰：“老夫女妻”，过以相与也。 ​ <a class="header-anchor" href="#《象》曰-老夫女妻-过以相与也。-​" aria-label="Permalink to “《象》曰：“老夫女妻”，过以相与也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“老夫女妻”之义。若老夫而有老妻，是依分相对。今老夫而得女妻，是过分相与也。老夫得女妻，是女妻以少而与老夫。老夫得少而更壮，是女妻过分而与夫也。女妻而得少夫，是依分相对。今女妻得老夫，是老夫减老而与少。女妻既得其老则益长，是老夫过分而与妻也，故云“过以相与”。《象》直云“老夫”、“女妻”，不云“枯杨生稊”者，“枯杨”则是老夫也，“生稊”则女妻也。其意相似，故《象》略而不言。</p><h2 id="九三-栋桡-凶。-​" tabindex="-1">九三：栋桡，凶。 ​ <a class="header-anchor" href="#九三-栋桡-凶。-​" aria-label="Permalink to “九三：栋桡，凶。 ​”">​</a></h2><p>王弼：居大过之时，处下体之极，不能救危拯弱，以隆其栋，而以阳处阳，自守所居，又应於上，系心在一，宜其淹弱而凶衰也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：居大过之时，处下体之极，以阳居阳，不能救危拯弱，唯自守而已。独应於上，系心在一，所以“凶”也。心既褊狭，不可以辅救衰难，故《象》云“不可以有辅也”。</p><h3 id="《象》曰-栋桡-之凶-不可以有辅也。-​" tabindex="-1">《象》曰：“栋桡”之凶，不可以有辅也。 ​ <a class="header-anchor" href="#《象》曰-栋桡-之凶-不可以有辅也。-​" aria-label="Permalink to “《象》曰：“栋桡”之凶，不可以有辅也。 ​”">​</a></h3><h2 id="九四-栋隆-吉。有它吝。-​" tabindex="-1">九四：栋隆，吉。有它吝。 ​ <a class="header-anchor" href="#九四-栋隆-吉。有它吝。-​" aria-label="Permalink to “九四：栋隆，吉。有它吝。 ​”">​</a></h2><p>王弼：体属上体，以阳处阴，能拯其弱，不为下所桡者也，故“栋隆”吉也。而应在初，用心不弘，故“有它吝”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“栋隆吉”者，体居上体，以阳处阴，能拯救其弱，不为下所桡，故得栋隆起而获吉也。“有它吝”者，以有应在初，心不弘阔，故“有它吝”也。</p><h3 id="《象》曰-栋隆-之吉-不桡乎下也。-​" tabindex="-1">《象》曰：“栋隆”之吉，不桡乎下也。 ​ <a class="header-anchor" href="#《象》曰-栋隆-之吉-不桡乎下也。-​" aria-label="Permalink to “《象》曰：“栋隆”之吉，不桡乎下也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“栋隆之吉”，以其能拯於难，不被桡乎在下，故得“栋隆吉”。九四应初，行又谦顺，能拯於难，然唯只拯初，初谓下也。下得其拯，犹若所居屋栋隆起，下必不桡。若何得之，不被桡乎在下。但《经》文云“栋桡”，《彖》释“栋桡”者，本末弱也。以屋栋桡弱而偏，则屋下榱柱亦先弱。柱为本，栋为末，观此《彖》辞，是足见其义。故子产云：“栋折榱崩，侨将压焉。”以屋栋桡折，则榱柱亦同崩，此则义也。</p><h2 id="九五-枯杨生华-老妇得其士夫-无咎无誉。-​" tabindex="-1">九五：枯杨生华，老妇得其士夫，无咎无誉。 ​ <a class="header-anchor" href="#九五-枯杨生华-老妇得其士夫-无咎无誉。-​" aria-label="Permalink to “九五：枯杨生华，老妇得其士夫，无咎无誉。 ​”">​</a></h2><p>王弼：处得尊位，而以阳处阳，未能拯危。处得尊位，亦未有桡，故能生华，不能生稊；能得夫，不能得妻。处“栋桡”之世，而为“无咎无誉”，何可长哉！故生华不可久，士夫诚可丑也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>“九五枯杨生华”至“无咎无誉”。正义曰：“枯杨生华”者，处得尊位而以阳居阳，未能拯危，不如九二“枯杨生稊”。但以处在尊位，唯得“枯杨生华”而巳。言其衰老，虽被拯救，其益少也。又似年老之妇，得其彊壮士夫，妇已衰老，夫又彊大，亦是其益少也。所拯难处少，才得无咎而已，何有声誉之美？故“无咎无誉”也。○注“处得尊位”至“诚可丑也”。○正义曰：“处得尊位，亦未有桡”者，以九三不得尊位，故有栋桡。今九五虽与九三同以阳居阳，但九五处得尊位，功虽未广，亦未有桡弱。若其桡弱，不能拯难，不能使“枯杨生华”也。以在尊位，微有拯难，但其功狭少，但使“枯杨生华”而已，“不能生稊”也。“能得夫，不能得妻”者，若拯难功阔，则“老夫得其女妻”，是得少之甚也。今既拯难功狭，但能使老妇得士夫而已，不能使女妻，言老妇所得利益薄少，皆为拯难功薄，故所益少也。</p><h3 id="《象》曰-枯杨生华-何可久也-老妇士夫-亦可丑也。-​" tabindex="-1">《象》曰：“枯杨生华”，何可久也？老妇士夫，亦可丑也。 ​ <a class="header-anchor" href="#《象》曰-枯杨生华-何可久也-老妇士夫-亦可丑也。-​" aria-label="Permalink to “《象》曰：“枯杨生华”，何可久也？老妇士夫，亦可丑也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“枯杨生华，何可久”者，枯稿之杨，被拯才得生华，何可长久？寻当衰落也。“老妇士夫，亦可丑也”者，妇当少稚於夫，今年老之妇，而得彊壮士夫，亦可丑辱也。此言九五不能广拯衰难，但使“枯杨生华”而已，但使“老妇得其士夫”而已。拯难狭劣，故不得长久，诚可丑辱，言不如九二也。</p><h2 id="上六-过涉灭顶-凶-无咎。-​" tabindex="-1">上六：过涉灭顶，凶，无咎。 ​ <a class="header-anchor" href="#上六-过涉灭顶-凶-无咎。-​" aria-label="Permalink to “上六：过涉灭顶，凶，无咎。 ​”">​</a></h2><p>王弼：处太过之极，过之甚也。涉难过甚，故至于“灭顶凶”。志在救时，故不可咎也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处大过之极，是过越之甚也。以此涉危难，乃至於灭顶，言涉难深也。既灭其顶，所以“凶”也。“无咎”者，所以涉难灭顶，至于凶亡，本欲济时拯难，意善功恶，无可咎责。此犹龙逄、比干，忧时危乱，不惧诛杀，直言深谏，以忤无道之主，遂至灭亡。其意则善，而功不成，复有何咎责？此亦“过涉灭顶凶无咎”之象，故《象》云“不可咎”，言不可害於义理也。</p><h3 id="《象》曰-过涉-之凶-不可咎也。-​" tabindex="-1">《象》曰：“过涉”之凶，不可咎也。 ​ <a class="header-anchor" href="#《象》曰-过涉-之凶-不可咎也。-​" aria-label="Permalink to “《象》曰：“过涉”之凶，不可咎也。 ​”">​</a></h3><p>王弼：虽凶无咎，不害义也。</p>',70)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
